package net.neoforged.neoforge.common.extensions;public interface ILivingEntityExtension{default net.minecraft.world.entity.LivingEntity self(){return (net.minecraft.world.entity.LivingEntity)this;}default boolean canDrownInFluidType(net.neoforged.neoforge.fluids.FluidType type){if(type==net.neoforged.neoforge.common.NeoForgeMod.WATER_TYPE.value())return !self().canBreatheUnderwater();return type.canDrownIn(self());}}
